-- ★高校 5154件を学校マスタに投入する（2026-09-28 / 柴さんの指示）
--
-- ── 出典 ────────────────────────────────────────────────────────────────────
-- 文部科学省「学校コード」**令和7年5月1日時点（確定版）**
--   https://www.mext.go.jp/b_menu/toukei/mext_01087.html
--   東日本 20251226-mxt_chousa01-000011635_2.csv（4,394,598 バイト）
--   西日本 20251226-mxt_chousa01-000011635_4.csv（3,149,443 バイト）
--
-- ⚠️ **暫定版（令和8年）ではなく確定版を使った。** 高校は年に数校しか動かないので、
--    新しさより確定していることを採った（柴さんの判断）。
--
-- ── 何を入れるか（実測）──────────────────────────────────────────────────
--
-- | | 件数 |
-- |---|---|
-- | D1(高校) | 5,093 |
-- | D2(中等教育学校) | 61 |
-- | **合計** | **5154** |
-- | うち廃止済み（`closed_at` あり） | **193** |
--
-- ⚠️★**廃止校も入れる**（柴さんの判断）。学歴は過去の話で、2023年に廃止された高校を
--    2010年に卒業した人が実在する。入れないとその人は自由入力にしかならず、
--    **まさに避けたい表記ゆれになる。**
-- ⚠️★**分校も入れる**（「岩手県立杜陵高等学校奥州校」など）。本人がそう名乗るため。
-- ⚠️★**中等教育学校（D2）も `highschool` として入れる。** 中高一貫だが卒業段階は高校。
--    外すと61校が自由入力に落ちる。
--
-- ── 何を入れないか ──────────────────────────────────────────────────────────
-- ⚠️★**`name_kana` は入れない。文科省データに読み仮名が無い。**
--    機械変換すると誤りが混ざる（CLAUDE.md「推測値を投入しない」）。**NULL のまま。**
-- ⚠️★**`logo_letter` / `logo_gradient` も入れない。** 既存37件は**学校ごとに手で選んだ色**で、
--    5,000校ぶんを機械生成すると意味の無い色が並ぶ。
--    ⚠️ `LetterCircle` は gradient が NULL なら既定色に落ち、`logo_letter` も無ければ
--       `SchoolLogoImg` が `GraduationCap` を出す（3段階フォールバック）。**壊れない。**
-- ⚠️ 所在地・郵便番号は入れない。**都道府県だけ**（同名の学校を見分けるのが目的）。
--
-- ── 都道府県 ────────────────────────────────────────────────────────────────
-- ⚠️★**文科省の表記は「青森」「沖縄」で県が付かない。**
--    src/lib/utils/location.ts の PREFECTURES（「青森県」「沖縄県」）に**揃えてある。**
--    ⚠️ 揃えないと求職者側の都道府県フィルタと噛み合わない。
--    ⚠️ 変換は**都道府県番号**（01〜47）で引いた。名前の前方一致にしない。
--    実測: 47種すべて PREFECTURES に含まれることを確認済み。
--
-- ── 既存4件の扱い ──────────────────────────────────────────────────────────
-- ⚠️★**重複させない。** 既に入っている高校4件は、**名前が文科省データと完全一致する**
--    ことを実測してから学校コードを紐づける（下の UPDATE）。
--    ⚠️ 4件とも文科省データに**1件だけ**存在することを確認済み（同名の別校ではない）。
--    ⚠️ 先に UPDATE で school_code を持たせるので、以降は UNIQUE が INSERT を弾く。
--
-- ⚠️ 作業前ダンプ: .dumps/20260928-1649-ow_schools.sql（11,126 バイト / 37行）

-- ── ① 既存4件に学校コードと都道府県を紐づける ─────────────────────────────
update public.ow_schools set school_code = 'D125220100032', prefecture = '滋賀県'
 where name = '滋賀県立東大津高等学校' and type = 'highschool' and school_code is null;
update public.ow_schools set school_code = 'D111210000986', prefecture = '埼玉県'
 where name = '埼玉県立朝霞西高等学校' and type = 'highschool' and school_code is null;
update public.ow_schools set school_code = 'D136220100011', prefecture = '徳島県'
 where name = '徳島県立城東高等学校' and type = 'highschool' and school_code is null;
update public.ow_schools set school_code = 'D128310000495', prefecture = '兵庫県'
 where name = '滝川第二高等学校' and type = 'highschool' and school_code is null;

do $$
declare n bigint;
begin
  select count(*) into n from public.ow_schools where school_code is not null;
  if n <> 4 then
    raise exception '既存の紐づけが想定（4件）と違う: %。中止する', n;
  end if;
end $$;

