-- ⚠️ 検算。**「INSERT が通った」だけでは足りない**ので、測った値で確かめる。
do $$
declare n bigint; total bigint; hs bigint; closed bigint; dup bigint;
begin
  select count(*) into total from public.ow_schools;
  if total <> 5187 then raise exception '学校マスタの行数が想定（5187）と違う: %', total; end if;

  select count(*) into hs from public.ow_schools where type='highschool';
  if hs <> 5154 then raise exception '高校が想定（5154）と違う: %', hs; end if;

  select count(*) into closed from public.ow_schools where closed_at is not null;
  if closed <> 193 then raise exception '廃止校が想定（193）と違う: %', closed; end if;

  -- ★既存4件を重複させていないこと。**名前で直接見る**（1件ずつであること）
  select count(*) into n from (
    select name from public.ow_schools
     where name in ('滋賀県立東大津高等学校','埼玉県立朝霞西高等学校','徳島県立城東高等学校','滝川第二高等学校')
     group by name having count(*) <> 1
  ) s;
  if n <> 0 then
    raise exception '既存の高校 % 件が重複している。①の UPDATE が当たっていない', n;
  end if;

  -- ★同名の別校は24組ある（実在する別の学校）。**増えていないこと**を見る
  --   ⚠️★**「13組」と書いて一度ガードに止められた**（2026-09-28）。
  --      13 は「**都道府県が違う**組」の数で、**同一県内の11組を落としていた。**
  --      ⚠️ 同名かつ同県が11組ある以上、**都道府県を添えても見分けられない組が残る**
  --         （ピッカーの表示を決めるときに読むこと）。
  select count(*) into dup from (
    select name from public.ow_schools where type='highschool' group by name having count(*) > 1
  ) s;
  if dup <> 24 then
    raise exception '同名の高校が想定（24組）と違う: %組', dup;
  end if;

  select count(*) into n from public.ow_schools where type='highschool' and prefecture is null;
  if n <> 0 then raise exception '都道府県が空の高校が % 件ある', n; end if;

  select count(*) into n from public.ow_schools where type='highschool' and school_code is null;
  if n <> 0 then raise exception '学校コードが空の高校が % 件ある', n; end if;

  -- ★高校以外は動いていないこと
  select count(*) into n from public.ow_schools where type <> 'highschool';
  if n <> 33 then raise exception '高校以外が想定（33）と違う: %', n; end if;

  raise notice '高校 % 件（うち廃止 %）/ 全体 % 件 / 同名 %組', hs, closed, total, dup;
end $$;
